$path='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\zh-CN\story\chapter2s2.ks'
$m=@{
846='离开清水寺后，我们来到下一家以抹茶芭菲闻名的咖啡店。[p]';848='「原来世界小姐也吃芭菲啊。」[p]';851='「怎么，你也是那种到了京都就一定要先吃八桥的人？」[p]';853='「不，我没那么奇怪的执着……」[p]';855='看来不管多么豪迈的人，多少也会吃点甜食。[p]';856='明明才认识两天，我似乎已经把世界小姐看得太神圣了。[p]';857='也许她的可怕已经刻进我尚未察觉的更深层――刻进了本能里。[p]';859='我用勺子舀起世界小姐请客的抹茶芭菲。[p]';860='明明请了咖啡店的假，却在另一家咖啡店喝茶，总觉得有点淡淡的罪恶感。[p]';861='不过这只是应世界小姐要求，介绍我以前由例前辈推荐的咖啡店，应该没问题。[p]';862='我一边向看不见的什么东西辩解，一边把顺滑的冰淇淋含入口中。[p]';865='「……真好啊，冰淇淋。」[p]';867='我忽然望向旁边，发现瞳一脸想吃地盯着顶端的樱桃。[p]';868='我当然很想喂她，可在有第三者注视的情况下，不能把勺子伸向虚空。[p]';870='既然味觉通过大脑直接共享，就让她忍耐一下吧。[p]';872='「……那个，世界小姐，可以问你一件事吗？」[p]';875='「什么事？说吧，小鬼。」[p]';877='小鬼……我不知道世界小姐究竟多大，但她也还是小鬼的年纪吧。[p]';879='「昨天例前辈说，这个仪式没有完全一致的先例。」[p]';880='「说到底，魔法仪式是很容易举行的东西吗？」[p]';882='「这个问题有两个答案。」[p]';883='「第一，只是举行仪式的话并不难。仪式说到底，就是遵循特定步骤施展魔法的过程。」[p]';884='「说得极端一点，只要知道方法，即使不懂魔法的外行也能完成。」[p]';886='「连我也可以？」[p]';888='「当然。不过就算做到，顶多也只能召来一位通灵者吧。」[p]';890='「不，外行能召来通灵者已经很厉害了吧。」[p]';892='只懂“魔法”这个词的普通人，顶多只能装作召来了通灵者。[p]';895='「不过这只是简单仪式。第二个答案是，要举行这种规模的仪式并不容易。」[p]';896='「或者说，在现代大概不存在能再现这种等级仪式的魔术师。」[p]';898='「在现代……？」[p]';901='「魔法已经很古老了。」[p]';903='「古老……除了东西方之外，魔法也有新旧之分吗？」[p]';905='「准确来说，现在的魔法比过去衰退了。」[p]';906='「魔法是“无知之知”――依靠人类对神秘与不可思议的认知而成立的力量。占卜或宗教就是身边的例子。」[p]';907='「但近几百年来科学突飞猛进，未知被解明，现象被赋予名称――」[p]';908='「人类的无知减少，魔法的力量也随时代发展而衰退。」[p]';910='魔法的衰退。也就是说，这个仪式是用类似奥帕兹、现代已经失传的技术制造的吗？[p]';913='「不能断言，但几乎肯定是这样。仪式的做法也异常古老……」[p]';914='「这不是顾忌现代人的目光、畏手畏脚使用的魔法，而是魔术全盛时代价值观下的大型魔法。」[p]';916='确实，不是把参加者集中在一间房里，而是把整座城市作为仪式对象，[p]';917='即使是外行也看得出规模有多大。[p]';920='「就我个人而言，我最喜欢这种华丽的做法……」[p]';921='「但黑幕的做法和我合拍，说明他大概不是适应现代的正经魔术师。」[p]';923='「……世界小姐，如果黑幕是过去的魔术师，你会怎么办？」[p]';925='「不管是过去还是现在，都和我无关。」[p]';927='「无论受害者还是加害者，我都会平等地抢走所有人的铃；恶魔出现后也把它打趴，结束一切。」[p]';928='「这就是这次委托给我的全部工作。」[p]';931='世界小姐把勺子丢进空芭菲杯，露出不怀好意的犬齿。[p]';932='绝对的自信――那种丝毫不考虑自己会犯错的[ruby text="ごうまん"]傲慢，既耀眼，又令人羡慕、嫉妒。[p]';946='陪她逛了几处寺社后，来到黄昏时分。[p]';947='我和世界小姐在观光休息时又去了另一处名胜――如今我独自站在鸭川沿岸高架桥下的铺装路上。[p]';949='『――嗯，抱歉，临时有点事。你在这里等着。』[p]';951='世界小姐只留下这句话离开，转眼已经快十五分钟。[p]';952='既然有事，解散不就好了――在我发自内心想尽快获得自由地提出建议前――[p]';953='或者说，她根本没听我回答就走了，我想回家也回不去，只能被困在鸭川。[p]';954='……算了，也没办法。反正没人可以抱怨，只能耐心等。[p]';955='擅自逃走的话，之后更可怕。[p]';958='「她真是个超级自由的人呢。」[p]';960='「与其说自由，不如说蛮横……魔术师都这样吗？」[p]';963='「那种大方的性格，应该是世界小姐独有的吧……？」[p]';965='把目中无人的态度说成大方，瞳真擅长用委婉的方式评价他人。[p]';968='「……夕阳好美。映在河面上，闪闪发光。」[p]';970='鸭川的水今天也很清澈。虽然还没到能直接饮用的程度，却足够干净，可以下河玩耍。[p]';973='「壹十，你冷不冷？」[p]';975='「没事。我穿着校服，虽然快入冬了，风还不冷。」[p]';977='水边比城市更容易冷却空气，但还没冷到让人发抖。[p]';978='如果日落前是这个温度，到了晚上应该也能正常四处走动。[p]';980='「对了，现在还感觉不到铃之持有者的位置吗？」[p]';983='「对不起，还是完全感觉不到。大概日落后还要过一段时间，铃的力量才会开始活性化。」[p]';985='「这样啊，那还得再等一会儿。」[p]';987='仪式参加者――铃之持有者一共有七人。其中三人昨晚被夺走铃的魔力，已经出局。[p]';988='剩下四人是我、世界小姐、打倒两名铃之持有者的神秘魔术师，以及一个至今未被提及的铃之持有者。[p]';990='「瞳，像你昨天说的，打倒铃之持有者、收集魔力，就能增强魔法力量，是真的吗？」[p]';993='「嗯。只是感觉上的判断……昨天打倒塔堂先生时，我确实感觉壹十的铃之力增强了。」[p]';995='既然瞳这样感觉，推测应该没错。[p]';996='打倒铃之持有者会增强铃的魔力，也能在召唤魔法战斗中取得优势。[p]';997='既然如此，趁我目前还没和已知最强的铃之持有者――世界小姐敌对，应该尽可能多收集铃的魔力。[p]';999='「明天放假，今晚就在街上散步到晚一点吧。」[p]';1002='「好耶！我期待夜晚散步。」[p]';1006='瞳把喜悦清楚地写在脸上。[p]';1008='被心爱少女天真的笑容温暖着，我正要为夜间行动思考巡逻路线――就在这时。[p]';1011='「――壹十，后面！」[p]';1015='能在最后关头察觉，是因为眼前原本舒展的她，表情突然变成了严峻的焦急。[p]';1017='我回应瞳的喊声，反射性地把握着的木刀向后举起。[p]';1020='――铛的一声，沉闷的撞击声响起，冲击与麻痹传到右臂。[p]';1021='不过，多亏无意识的防卫行动和被半强迫握在手里的木刀，[p]';1022='我成功挡下了朝后脑勺挥来的球棒。[p]';1025='「什么――这都能挡住？」[p]';1027='我用脚稳住向后踉跄的身体，将木刀架在中线，望向偷袭者。[p]';1029='两个和我年纪相仿的年轻男人，手里分别拿着球棒和锤子。[p]';1030='不能凭外表判断人，但他们衣着邋遢，又拿着用于殴打的钝器――[p]';1031='――再加上明确的攻击意图，显然就是我的敌人。[p]';1033='「……不只是前面两个人。高架桥另一侧的草丛阴影里，还藏着两个人。」[p]';1035='（喂，真的假的……）[p]';1037='两个人我都未必打得过，更何况被双倍人数夹击，恐怕连逃跑都不允许。[p]';1039='「……你们是什么人？」[p]';1041='「没什么身份。只是奉命把你带走的人。」[p]';1043='他们似乎不打算轻易吐露身份，但在这种情况下袭击我的理由只有一个。[p]';1044='铃之持有者――他们趁铃的魔法无法使用时，试图用暴力抢夺。[p]';1045='我正面临昨晚世界小姐警告过的事态――面临生命危险。[p]';1046='要不要大声呼救？[p]';1047='不，他们或许也算准了时机；高架桥下――地面视线的死角处，完全看不到其他人影。[p]';1048='在这种情况下，就算大声呼喊，也只会被球棒和锤子强行封住嘴。[p]';1049='可正面交战必败无疑。[p]';1050='我自信跑步不会输，但前后都被封锁，逃走前就会被打倒。[p]';1051='进退两难，四面楚歌。局面已经无可挽回地陷入死局。[p]';1054='既然如此，为了至少不受无谓的伤，只能老实投降，跟他们走――[p]';1057='「――壹十，把木刀举到前面。」[p]';1059='（……瞳？）[p]';1061='即使在这种穷途末路的情况下，青梅竹马的声音仍清澈得无以复加。[p]';1063='「把铃的魔力[ruby text="こ"]注入木刀。」[p]';1065='（铃的魔力……太阳升起时，不是不能用吗……）[p]';1068='「没关系，壹十一定能做到。感觉上和昨晚从塔堂先生那里夺取铃的魔力相反――」[p]';1069='「――从右臂释放魔法力量，整理魔力流，注入木刀前端。」[p]';1072='我任由瞳在耳边低语，平复内心波澜，将意识集中到右臂的铃上。[p]';1074='铃的力量，魔法的力量。我用肌肤感受看不见的东西，操纵无法触碰的流动，[p]';1075='将胸中膨胀的白色空气般感觉，推向刀尖。[p]';1079='「……怎么，放弃抵抗了吗？」[p]';1083='「既然想服从，就乖乖跟我们……走…………！？」[p]';1087='起初，我以为是错觉。[p]';1089='风从大地吹起，虚无空间传出刺耳声响，手中的木刀缠上了光的粒子。[p]';1090='然后――――[p]';1092='「――喂、喂！那个女人是怎么回事！？」[p]';1094='「她到底从哪里……浮、浮在空中……！？」[p]';1098='两个男人的视线从我手边转向后方――[p]';1100='转向瞳所在的位置。[p]';1102='（他们看得见瞳――！？）[p]';1104='神秘、不可思议、本不该发生的现象。[p]';1105='虽然短暂得几乎会在眨眼间错过――[p]';1106='――那名属于妄想、空想与幻想的少女，化作人形显现于世。[p]';1110='「――[ruby text="Seventeenth The Star"]ⅩⅦ之星，';1112='『[ruby text="イノセントスター"]许愿之星』！！[p]';1116='回应瞳的话语，世界中闪过数道光芒。[p]';1118='[ruby text="かくかく"]赫赫一闪的耀眼光芒让我不由得闭上双眼。[p]';1120='再次睁眼时映入视野的，是发出呻吟、倒在地上的男人们。[p]';1122='「刚才那是什么……」[p]';1124='回头一看，夹击我们的另外两个男人也昏了过去。[p]';1125='刚才那一瞬――一闪之间，她竟把包围我们的敌人一网打尽？[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content $path -Encoding UTF8); foreach($n in $m.Keys){$lines[$n-1]=$m[$n]}; [IO.File]::WriteAllLines($path,$lines,[Text.UTF8Encoding]::new($false))
